<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Auth;use App\Core\Crypto;use App\Core\DB;use App\Core\I18n;use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\Totp;use App\Models\ApiKey;use App\Models\AuditLog;use App\Models\Invoice;use App\Models\License;use App\Models\Order;use App\Models\Plan;use App\Models\Release;use App\Models\User;use App\Services\InvoiceService;use App\Services\LicenseService;final class AccountController extends Controller{protected string $layout='layouts/account';public function dashboard(Request $Y):Response{$d=$this->user();$f=License::forUser((int)$d['id']);foreach($f as&$P){$P['plan']=Plan::find((int)$P['plan_id']);$P['activations']=License::activeActivationCount((int)$P['id']);}unset($P);$H=(bool)DB::scalar('SELECT COUNT(*) FROM {{licenses}} l JOIN {{plans}} p ON p.id = l.plan_id WHERE l.user_id = ? AND p.slug = ?',[(int)$d['id'],'trial']);return $this->view('account/dashboard',['licenses'=>$f,'orders'=>array_slice(Order::forUser((int)$d['id']),0,5),'release'=>Release::latest('stable'),'hasTrial'=>$H,'meta'=>['title'=>t('account.dashboard')]]);}public function licenses(Request $Y):Response{$h=$this->user();$F=License::forUser((int)$h['id']);foreach($F as&$p){$p['plan']=Plan::find((int)$p['plan_id']);$p['activations']=License::activeActivationCount((int)$p['id']);}unset($p);return $this->view('account/licenses',['licenses'=>$F,'meta'=>['title'=>t('account.licenses')]]);}private function _14wtm(int $c):?array{$Q=License::withPlan($c);return $Q&&(int)$Q['user_id']===Auth::id()?$Q:null;}public function license(Request $E,string $T):Response{$M=$this->_14wtm((int)$T);if(!$M){return $this->redirect(url('/account/licenses'));}return $this->view('account/license',['license'=>$M,'activations'=>License::activations((int)$M['id']),'events'=>License::events((int)$M['id'],30),'plans'=>array_values(array_filter(Plan::publicPlans(),fn($d)=>$d['slug']!=='trial')),'meta'=>['title'=>t('account.license')]])