 = ?',[(int)$d['id'],'trial']);if(!$P||$B||!(int)$P['is_active']){$this->flash('error',t('license.trial_already'));return $this->redirect(url('/account'));}$S=LicenseService::create((int)$d['id'],$P,'month');try{(new \App\Core\Mailer())->sendTemplate($d['email'],'order_confirmation',['user'=>$d,'order'=>null,'license'=>$S,'plan'=>$P,'invoice'=>null],$d['lang']?:lang(),$d['name']);}catch(\Throwable){}$this->flash('success',t('license.trial_started'));return $this->redirect(url('/account/licenses/'.$S['id']));}public function invoices(Request $W):Response{$q=$this->user();return $this->view('account/invoices',['invoices'=>Invoice::forUser((int)$q['id']),'orders'=>Order::forUser((int)$q['id']),'meta'=>['title'=>t('account.invoices')]]);}private function _11auv(int $c):?array{$f=Invoice::find($c);return $f&&(int)$f['user_id']===Auth::id()?$f:null;}public function invoicePdf(Request $i,string $B):Response{$d=$this->_11auv((int)$B);if(!$d){return $this->redirect(url('/account/invoices'));}return Response::raw(InvoiceService::pdf($d,lang()),'application/pdf')->withHeader('Content-Disposition','inline; filename="'.$d['number'].'.pdf"');}public function invoiceHtml(Request $d,string $H):Response{$A=$this->_11auv((int)$H);if(!$A){return $this->redirect(url('/account/invoices'));}return $this->view('account/invoice_print',['invoice'=>$A],null);}public function downloads(Request $e):Response{return $this->view('account/downloads',['stable'=>Release::latest('stable'),'beta'=>Release::latest('beta'),'releases'=>Release::castAll(Release::query()->where('is_active',1)->orderBy('published_at','DESC')->limit(20)->get()),'public_key'=>Crypto::publicKeyB64(),'meta'=>['title'=>t('account.downloads')]]);}public function profile(Request $g):Response{return $this->view('account/profile',['user'=>$this->user(),'countries'=>CheckoutController::countries(),'meta'=>['title'=>t('account.profile')]]);}public function profileSave(Request $q):Response{if($m=$this->validate($q,['name'=>'required|ma