F->str('method')==='email'?'email':'totp';if($I==='totp'){$b=Session::get('totp_setup');if(!$b||!Totp::verify($b['secret'],$F->str('code'))){$this->flash('error',t('auth.invalid_code'));return $this->redirect(url('/account/security'));}User::update((int)$p['id'],['two_factor'=>'totp','totp_secret'=>Crypto::encrypt($b['secret'])]);Session::remove('totp_setup');}else{User::update((int)$p['id'],['two_factor'=>'email','totp_secret'=>null]);}AuditLog::log('account.2fa_enabled',$p['email'],['method'=>$I]);$this->flash('success',t('account.2fa_enabled'));return $this->redirect(url('/account/security'));}public function twoFactorDisable(Request $h):Response{$V=$this->user();if(!Crypto::verifyPassword((string)$h->input('current_password'),$V['password_hash'])){$this->flash('error',t('auth.wrong_password'));return $this->redirect(url('/account/security'));}User::update((int)$V['id'],['two_factor'=>'none','totp_secret'=>null]);AuditLog::log('account.2fa_disabled',$V['email']);$this->flash('success',t('account.2fa_disabled'));return $this->redirect(url('/account/security'));}public function apiKeys(Request $a):Response{$s=$this->user();$E=Session::get('new_api_key');Session::remove('new_api_key');return $this->view('account/api_keys',['keys'=>ApiKey::where('user_id',(int)$s['id']),'newKey'=>$E,'meta'=>['title'=>t('account.api_keys')]]);}public function apiKeyCreate(Request $q):Response{$U=$this->user();if(ApiKey::query()->where('user_id',(int)$U['id'])->count()>=10){$this->flash('error',t('account.api_key_limit'));return $this->redirect(url('/account/api-keys'));}$w=ApiKey::generate((int)$U['id'],$q->str('name')?:'API');Session::set('new_api_key',$w['plain']);AuditLog::log('account.api_key_create',$U['email']);return $this->redirect(url('/account/api-keys'));}public function apiKeyDelete(Request $P,string $e):Response{DB::delete('api_keys','id = ? AND user_id = ?',[(int)$e,Auth::id()]);$this->flash('success',t('common.deleted'));return $this->redirect(url('/account/api-keys'));